spark.sql(r"""
WITH latest AS (
  SELECT
    e.shipment_id,
    e.event_code,
    e.event_ts,
    ROW_NUMBER() OVER (PARTITION BY e.shipment_id ORDER BY e.event_ts DESC, e.event_id DESC) AS rn
  FROM dbo.carrier_tracking_events AS e
  WHERE
    e.event_ts <= :v_as_of
)
MERGE INTO dbo.shipments AS s
USING (
  SELECT
    *
  FROM latest AS l
  WHERE
    l.event_code = 'DL'
) AS l
ON l.shipment_id = s.shipment_id AND l.rn = 1
WHEN MATCHED AND s.status <> 'DELIVERED' THEN UPDATE SET
  s.status = 'DELIVERED',
  s.delivered_at = l.event_ts,
  s.last_status_update = :v_as_of
""", args={"v_as_of": v_as_of})

