spark.sql(r"""
MERGE INTO dbo.shipments AS s
USING (
  SELECT DISTINCT
    e.shipment_id
  FROM dbo.carrier_tracking_events AS e
  WHERE
    e.event_code = 'EX' AND e.event_ts <= :v_as_of
) AS e
ON e.shipment_id = s.shipment_id
WHEN MATCHED AND NOT s.status IN ('DELIVERED', 'EXCEPTION') THEN UPDATE SET
  s.status = 'EXCEPTION',
  s.last_status_update = :v_as_of
""", args={"v_as_of": v_as_of})

